def _four(g, r, c, p):
    for dr, dc in ((0, 1), (1, 0), (1, 1), (1, -1)):
        n = 1
        for s in (1, -1):
            rr, cc = r + s * dr, c + s * dc
            while 0 <= rr < 6 and 0 <= cc < 7 and g[rr][cc] == p:
                n += 1
                rr += s * dr
                cc += s * dc
        if n >= 4:
            return True
    return False


def _dbl(b, p):
    # number of moves for player p that create two or more playable winning cells
    g = [row[:] for row in b.grid]
    cnt = 0
    for c in b.legal:
        r = b.heights[c]
        if _four(g, r, c, p):
            continue
        g[r][c] = p
        h = list(b.heights)
        h[c] += 1
        w = 0
        for cc in range(7):
            rr = h[cc]
            if rr < 6 and _four(g, rr, cc, p):
                w += 1
                if rr + 1 < 6 and _four(g, rr + 1, cc, p):
                    w += 1
        g[r][c] = 0
        if w >= 2:
            cnt += 1
    return cnt


def fires(b):
    return _dbl(b, 2) + _dbl(b, 1) > 0


def level(b):
    n = _dbl(b, 2) + _dbl(b, 1)
    return min(9, 4 * n)

def _windows(b, p):
    # horizontal 4-windows with >=2 stones of p, none of the other player, every empty cell playable now
    out = []
    for r in range(6):
        for c0 in range(4):
            cells = [(r, c0 + k) for k in range(4)]
            vals = [b.grid[rr][cc] for rr, cc in cells]
            if any(v not in (0, p) for v in vals):
                continue
            n = sum(1 for v in vals if v == p)
            if n < 2:
                continue
            if all(b.heights[cc] == rr for (rr, cc), v in zip(cells, vals) if v == 0):
                out.append((r, c0, n))
    return out


def fires(b):
    return len(_windows(b, 2)) > 0


def level(b):
    w = _windows(b, 2)
    if not w:
        return 0
    return min(9, 2 + 2 * len(w) + 2 * max(n for _, _, n in w) - 4)

